def check_brakes(run, limits):
    if run.steps >= limits.max_steps:
        return 'max_steps'
    if run.input_tokens + run.output_tokens >= limits.max_tokens:
        return 'budget'
    if run.cost >= limits.max_cost:
        return 'budget'
    if run.elapsed >= limits.deadline:
        return 'deadline'
    if run.same_call_count >= limits.max_repeats:
        return 'repeat'
    return None   # keep going

def step(run, limits):
    reason = check_brakes(run, limits)
    if reason:
        return finish(run, stop_reason=reason, partial=run.best_so_far)
    return run_next_step(run)
